// The control that makes the central test mean anything:
func TestWriteWorkItem_ToolPageWithItsToolIsUntouched(t *testing.T) {
	mock.ExpectBegin()
	expectRebuildPolicyRead(mock, pageID, "generic")   // generic AND not a shell
	// The declaration probe is deliberately NOT scripted: reaching it would be the
	// bug, and ExpectationsWereMet cannot catch a query never made — so the
	// assertion is that the row inserted UNPARKED ($11 handler intact, $12 detected).
	mock.ExpectExec("INSERT INTO site_work_items").WithArgs(..., "page-build-handler", "detected", ...)
}

func TestToolShellKillSwitch_DisarmsOnlyTheNewArm(t *testing.T) {
	t.Setenv(disableToolShellRefusalEnv, "1")
	if refused, _ := genericBuildRefusal("generic", true); refused { t.Error("switch inert") }
	// guard-in-series check: the OWNED arm must still fire
	if refused, class := genericBuildRefusal("owned", false); !refused || class != refusalOwned {
		t.Errorf("kill switch disarmed the OWNED arm too — it must scope to the new arm")
	}
	// and the SQL half must agree with the Go half, or selection and verdict diverge
	if strings.Contains(genericBuildExclusionSQL(), "component_level = 'tool'") { t.Error(...) }
}

